/**
 * Populate the column, looks through the column object and populates
 * The associated div
 * @param {object} e
 * @param {string} t
 */
function populate_col(e, t) {
  const o = document.getElementById(t),
    n = document.createElement("h1");
  (n.textContent = e.name), o.appendChild(n);
  for (const t in e.items) {
    var i = document.createElement("p");
    var l = document.createElement("a");
    l.href = e.items[t];
    l.textContent = t;
    i.appendChild(l), o.appendChild(i);
  }
}

function setupWelcomeMessage() {
  let e = new Date().getHours();
  (e = Math.floor(e / 6)), 4 == e && (e = 3);
  let t = "Good " + WELCOME_MESSAGE_TEMPLATE[e] + ", " + NAME;
  document.getElementById("welcome-string").innerHTML = t;
}

populate_col(col1, "col1");
populate_col(col2, "col2");
populate_col(col3, "col3");
populate_col(col4, "col4");
setupWelcomeMessage();
